#!/usr/bin/env bash
# Build every kernels/*.c (hand-written) and build/gen/*.c (generated by
# lib/kgen.aura, see scripts/gen_kernel.sh) into build/kernels/lib<name>.so.
#   CC      C compiler (default: cc)
#   CFLAGS  extra flags (default: -O2)
# Generated sources get no unused-label / unused-variable errors (the generator
# emits uniform labels). No -fwrapv: Int kernels use checked arithmetic
# (sink_ck_add/sub/mul/neg in sink_abi.h, fixnum range, fail-closed).
set -euo pipefail
here="$(cd "$(dirname "$0")" && pwd)"
root="$(cd "$here/.." && pwd)"
out="$root/build/kernels"
mkdir -p "$out"
CC="${CC:-cc}"
CFLAGS="${CFLAGS:--O2}"
# Value encoding header (single source, aura#4502): <aura>/lib/aura_value_abi.h
AURA_LIB="${AURA_LIB:-$(cd "$(dirname "${AURA_BIN:-/nonexistent}")/../lib" 2>/dev/null && pwd || true)}"
if [ -z "$AURA_LIB" ] || [ ! -f "$AURA_LIB/aura_value_abi.h" ]; then
  echo "error: AURA_LIB must point at an Aura lib/ with aura_value_abi.h (set AURA_BIN or AURA_LIB)" >&2
  exit 2
fi
abi_h="$AURA_LIB/aura_value_abi.h"
shopt -s nullglob
build_one() {  # src extra-flags tag
  local src="$1" extra="$2" tag="$3" name so
  name="$(basename "$src" .c)"
  so="$out/lib$name.so"
  if [ ! -f "$so" ] || [ "$src" -nt "$so" ] || [ "$here/sink_abi.h" -nt "$so" ] || [ "$abi_h" -nt "$so" ]; then
    # shellcheck disable=SC2086
    "$CC" $CFLAGS $extra -std=c11 -Wall -Wextra -Werror -shared -fPIC -fvisibility=hidden \
      -I"$here" -I"$AURA_LIB" -Wl,-Bsymbolic -o "$so" "$src" -lm
    echo "built build/kernels/lib$name.so$tag"
  fi
}
for src in "$here"/*.c; do build_one "$src" "" ""; done
for src in "$root"/build/gen/*.c; do
  build_one "$src" "-Wno-unused-label -Wno-unused-variable" " (generated)"
done
